-- name: GetMonitorIncident :one
SELECT * FROM monitor_incidents WHERE id = $1;

-- name: ListMonitorIncidents :many
SELECT * FROM monitor_incidents ORDER BY created_at DESC LIMIT $1 OFFSET $2;

-- name: CreateMonitorIncident :one
INSERT INTO monitor_incidents (team_id, monitor_id, app_id, opened_at, resolved_at, reason, last_value, notified)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
RETURNING *;

-- name: DeleteMonitorIncident :exec
