-- Hosbah queries.

-- name: OpenIncidentsOfApp :many
-- Team scope: the open incident (at most one) of each of an app's monitors.
SELECT * FROM monitor_incidents
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND resolved_at IS NULL;

-- name: OpenIncidentOfMonitor :one
SELECT * FROM monitor_incidents
WHERE monitor_id = sqlc.arg('monitor_id') AND team_id = sqlc.arg('team_id') AND resolved_at IS NULL;

-- name: AppIncidentFeed :many
-- Team scope: an app's incidents, newest first, keyset-paginated on (opened_at, id).
SELECT i.id, i.monitor_id, m.name AS monitor_name, m.kind AS monitor_kind, i.app_id, i.opened_at, i.resolved_at, i.reason, i.last_value, i.notified
FROM monitor_incidents i
JOIN monitors m ON m.id = i.monitor_id AND m.team_id = i.team_id
WHERE i.app_id = sqlc.arg('app_id') AND i.team_id = sqlc.arg('team_id')
  AND (sqlc.narg('before_at')::timestamptz IS NULL OR (i.opened_at, i.id) < (sqlc.narg('before_at')::timestamptz, sqlc.arg('before_id')::text))
ORDER BY i.opened_at DESC, i.id DESC
LIMIT sqlc.arg('limit_rows');

-- name: OpenMonitorIncident :one
-- Evaluator (system + team scope). A monitor has at most one open incident (partial unique index):
-- no row comes back when one is already open.
INSERT INTO monitor_incidents (team_id, monitor_id, app_id, opened_at, reason, last_value)
VALUES (sqlc.arg('team_id'), sqlc.arg('monitor_id'), sqlc.arg('app_id'), sqlc.arg('opened_at'), sqlc.arg('reason'), sqlc.arg('last_value'))
ON CONFLICT (monitor_id) WHERE resolved_at IS NULL DO NOTHING
RETURNING *;

-- name: TouchMonitorIncident :exec
-- Still failing: the incident keeps the latest reading.
UPDATE monitor_incidents SET last_value = sqlc.arg('last_value'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND resolved_at IS NULL;

-- name: ResolveMonitorIncident :one
UPDATE monitor_incidents SET resolved_at = sqlc.arg('resolved_at')::timestamptz, last_value = sqlc.arg('last_value'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND resolved_at IS NULL
RETURNING *;

-- name: ResolveIncidentsOfMonitor :exec
-- Team scope: a monitor that was switched off, or whose rule changed, no longer has an open incident.
UPDATE monitor_incidents SET resolved_at = sqlc.arg('resolved_at')::timestamptz, updated_at = now()
WHERE monitor_id = sqlc.arg('monitor_id') AND team_id = sqlc.arg('team_id') AND resolved_at IS NULL;

-- name: MarkMonitorIncidentNotified :exec
UPDATE monitor_incidents SET notified = true, updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: PublicOpenIncidentsByMonitorIDs :many
-- System scope, public endpoint: the open incident, if any, of each monitor a status page shows —
-- opened_at only (a reason can name internal hosts or IPs), matching PublicMonitorsByIDs's own no-team-data-leak shape
-- (internal/api/public.go).
SELECT id, monitor_id, opened_at FROM monitor_incidents
WHERE team_id = sqlc.arg('team_id') AND monitor_id = ANY(string_to_array(sqlc.arg('ids')::text, ',')) AND resolved_at IS NULL;
